    # Marked strokes are diagonal lines. Identify their orientation from
    # the longest straight run of nonzero cells.
    pts = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c]]
    runs = {}
    for r, c, v in pts:
        runs.setdefault(c-r, []).append((r, c, v))
