    # Select the coordinate whose groups contain the longer strokes.
    sum_groups, diff_groups = {}, {}
    for r, c, v in pts:
        sum_groups.setdefault(r+c, []).append(v)
        diff_groups.setdefault(c-r, []).append(v)
    sum_score = max(map(len, sum_groups.values()), default=0)
    diff_score = max(map(len, diff_groups.values()), default=0)
    use_sum = sum_score >= diff_score

    groups = sum_groups if use_sum else diff_groups
    anchors = {k: max(set(v), key=v.count) for k, v in groups.items()}
    keys = sorted(anchors)
    lo, hi = min(keys), max(keys)

    # Repeat the observed stripe motif in the diagonal coordinate.
    # Fill gaps by periodically extending the ordered anchor colors.
    period = hi - lo + 1
    for p in range(1, period + 1):
        if all(anchors[a] == anchors[b]
               for a in keys for b in keys if (a-b) % p == 0):
            period = p
            break

    residues = {k % period: v for k, v in anchors.items()}
    known = list(residues)
    for x in range(period):
        if x not in residues:
